async function uploadVideo(){const a=document.getElementById("videoFile"),t=document.getElementById("uploadStatus");if(!a.files[0])return alert("\u8BF7\u5148\u9009\u62E9\u4E00\u4E2A MP4 \u89C6\u9891");const n=new FormData;n.append("video",a.files[0]),t.innerText="\u6B63\u5728\u4E0A\u4F20\u5E76\u5207\u7247\uFF08FFmpeg \u8F6C\u6362\u4E2D\uFF0C\u8BF7\u7A0D\u5019...\uFF09";try{const e=await(await fetch("/api/upload",{method:"POST",body:n})).json();e.code===200?t.innerText=`\u5904\u7406\u6210\u529F\uFF01\u89C6\u9891 ID \u4E3A: ${e.videoId}\u3002...`:t.innerText="\u5931\u8D25: "+e.msg}catch{t.innerText="\u7F51\u7EDC\u8BF7\u6C42\u9519\u8BEF"}}const video_id="123";play(video_id);async function play(a){let t="",n="";try{const o=await(await fetch("/api/get_auth?video_id="+a)).json();n=o.token,t=o.url+"?token="+n}catch{console.log("\u7F51\u7EDC\u9519\u8BEF.")}var i=videojs("my-video");i.ready(function(){videojs.Vhs.xhr.beforeRequest=function(e){var o=e.uri;if(o.indexOf("token=")===-1){var r=o.indexOf("?")===-1?"?":"&";e.uri=o+r+"token="+n}return e}}),i.src({src:t,type:"application/x-mpegURL"})}
